/**
 * The board — every initiative, by state
 *
 * DEC-026 makes this a compiled sibling of DECISION-MAP.md: cross-cutting
 * rather than hat-scoped, because it answers "where is everything", which is
 * nobody's hat and everybody's question.
 *
 * It is generated by code with no skill in the loop. Every other compiled
 * artifact splits deterministic staging from synthetic condensation because
 * prose needs a model; the board needs none — it is structured state rendered
 * as a table, and a model here would only add a way for it to be wrong. That
 * is also why it is regenerated rather than staleness-gated: compact check
 * exists to catch a skill disagreeing with its sources, and there is no skill
 * here to disagree.
 *
 * DEC-006 holds without strain: moving a card means changing a record's
 * state. The board is never edited.
 */

import * as fs from 'node:fs';
import * as path from 'node:path';
import {
  readInitiatives,
  checkInitiativeState,
  type InitiativeEntry,
} from './initiatives.js';
import { readSourcedDriverSpecs } from './compact/records.js';
import { parseMeasureAnatomy, mitigatedBy } from './compact/measures.js';
import { readInitiativeGitState } from './initiative-git.js';

/** An exposure and the work, if any, planned to close it. */
export interface RoadmapRow {
  record: string;
  exposure: string;
  /** The initiative named by `mitigated-by`, or null. */
  mitigatedBy: string | null;
  /** That initiative's state, or null when it points nowhere or nowhere real. */
  mitigationState: string | null;
  /**
   * The filename stem of that initiative, for linking.
   *
   * Carried rather than derived from the id: `DEC-036` prefixes
   * initiative filenames with their creation date, so `<id>.md` is no longer
   * the path. A link built from the id would 404 on every dated file.
   */
  mitigationStem: string | null;
}

/**
 * Every recorded exposure, with the state of whatever is meant to close it.
 *
 * The state is the assurance level (DS-FORWARD-CLOSURE): nothing is a
 * confession, `exploring` means we know and are thinking, `proposed` means
 * committed with a bar, `building` means in flight. A reader can tell those
 * apart without opening anything, which a static risk register never allows.
 */
export function roadmapRows(
  opensprintDir: string,
  initiatives: readonly InitiativeEntry[]
): RoadmapRow[] {
  const stateOf = new Map(initiatives.map((i) => [i.id, i.state ?? i.status]));
  const stemOf = new Map(initiatives.map((i) => [i.id, i.stem]));
  const rows: RoadmapRow[] = [];

  for (const spec of readSourcedDriverSpecs(opensprintDir)) {
    if (spec.status !== 'active') continue;
    const exposure = parseMeasureAnatomy(spec.content).exposure;
    if (exposure === undefined) continue;

    const target = mitigatedBy(exposure);
    rows.push({
      record: spec.id,
      exposure: firstSentence(exposure),
      mitigatedBy: target,
      // A pointer at an initiative that does not exist resolves to null
      // rather than being reported as mitigated — a dangling pointer is a
      // confession wearing a plan's clothes.
      mitigationState: target === null ? null : stateOf.get(target) ?? null,
      mitigationStem: target === null ? null : stemOf.get(target) ?? null,
    });
  }
  return rows;
}

/** The exposure's first sentence, for a table cell. */
function firstSentence(text: string): string {
  const flat = text
    .split('\n')
    .filter((line) => !/^\s*(?:[-*]\s*)?(?:\*\*)?mitigated-by/i.test(line))
    .join(' ')
    .replace(/\s+/g, ' ')
    .trim();
  const stop = flat.search(/[.!?](\s|$)/);
  const sentence = stop === -1 ? flat : flat.slice(0, stop + 1);
  return sentence.length > 120 ? `${sentence.slice(0, 117)}…` : sentence;
}

export const BOARD_FILENAME = 'BOARD.md';

/**
 * Which section each state lands in, as an explicit map.
 *
 * If we group them, we track them by name in a constant. `attested` sits in
 * Doing rather than Done because the work is not closed until it is archived
 * — an attested initiative is still in flight.
 */
const SECTION_BY_STATE: Readonly<Record<string, string>> = {
  exploring: 'Backlog',
  proposed: 'Next',
  building: 'Doing',
  attested: 'Doing',
  completed: 'Done',
  declined: 'Declined',
};

/** What each mitigation state tells a reader about the risk. */
const ASSURANCE: Readonly<Record<string, string>> = {
  exploring: 'we know, we are thinking',
  proposed: 'committed, with a bar',
  building: 'in flight',
  attested: 'done, pending close',
  completed: 'closed',
  declined: '**dropped — the exposure stands**',
};

/** Rendered in this order, every one of them, empty or not. */
const SECTIONS = ['Backlog', 'Next', 'Doing', 'Done', 'Declined'] as const;

const SECTION_BLURB: Readonly<Record<string, string>> = {
  Backlog: 'Ideas captured, not yet triaged.',
  Next: 'Proposed — a bar is set, no work started.',
  Doing: 'In flight.',
  Done: 'Closed.',
  Declined: 'Considered and dropped. Kept because why it was declined is worth more than the idea.',
};

/**
 * The section an initiative belongs to.
 *
 * An initiative declaring no state is placed by its status, so one written by
 * an older release still appears. The state check reports it separately when
 * it is active — placing it is not the same as pretending it is fine.
 */
function sectionFor(entry: InitiativeEntry): string {
  if (entry.state !== undefined) {
    return SECTION_BY_STATE[entry.state] ?? 'Backlog';
  }
  return entry.status === 'completed' ? 'Done' : 'Backlog';
}

function progressOf(entry: InitiativeEntry): string {
  const live = entry.milestones.filter((m) => !m.superseded);
  if (live.length === 0) return '—';
  const done = live.filter((m) => m.done).length;
  const dropped = entry.milestones.length - live.length;
  return `${done}/${live.length}` + (dropped > 0 ? ` _(+${dropped} superseded)_` : '');
}

function nextMilestoneOf(entry: InitiativeEntry): string {
  const next = entry.milestones.find((m) => !m.done && !m.superseded);
  if (!next) return '—';
  return next.name || next.description.slice(0, 40);
}

/** Renders the board from the initiatives, deterministically. */
export function renderBoard(
  initiatives: readonly InitiativeEntry[],
  roadmap: readonly RoadmapRow[] = [],
  /** What git says per initiative id, where it knows. */
  gitStates: ReadonlyMap<string, import('./initiatives.js').InitiativeGitState> = new Map()
): string {
  const lines: string[] = [
    '# Board',
    '',
    'Compiled by `/opsp:compact` from `opensprint/initiatives/`. **Derived — do not edit.**',
    '',
    '**Moving a card means changing a record\'s state**, not editing this file. A peer of',
    '`DECISION-MAP.md`: cross-cutting rather than hat-scoped, so it is not a squad view (`DEC-026`).',
    '',
  ];

  if (initiatives.length === 0) {
    lines.push('No initiatives yet. `/opsp:backlog` creates the first one.', '');
  } else {
    for (const section of SECTIONS) {
      const members = initiatives.filter((entry) => sectionFor(entry) === section);
      lines.push(`## ${section}`, '', `${SECTION_BLURB[section]}`, '');
      if (members.length === 0) {
        lines.push('_Empty._', '');
        continue;
      }
      lines.push('| Initiative | State | Milestones | Next |', '|---|---|---|---|');
      for (const entry of members) {
        lines.push(
          `| [${entry.id}](initiatives/${entry.stem}.md) | ${entry.state ?? `_(none — status: ${entry.status})_`} | ${progressOf(entry)} | ${nextMilestoneOf(entry)} |`
        );
      }
      lines.push('');
    }
  }

  // DS-FORWARD-CLOSURE makes the roadmap the board's forward half, and it is
  // where exposures land. The section exists before it has content so the
  // reader learns the shape once rather than meeting it later.
  lines.push(
    '## Roadmap',
    '',
    'Every open exposure beside the state of the work planned to close it (`DS-FORWARD-CLOSURE`).',
    'An exposure pointing at nothing is a confession; one pointing at an initiative is a managed',
    'risk, and **that initiative\'s state is the assurance level**.',
    ''
  );
  if (roadmap.length === 0) {
    lines.push('_No exposures recorded._', '');
  } else {
    lines.push('| Record | Exposure | Mitigated by | Assurance |', '|---|---|---|---|');
    for (const row of roadmap) {
      const target =
        row.mitigatedBy === null
          ? '**nothing**'
          : row.mitigationState === null
            ? `\`${row.mitigatedBy}\` _(no such initiative)_`
            : `[${row.mitigatedBy}](initiatives/${row.mitigationStem}.md)`;
      const assurance =
        row.mitigatedBy === null
          ? 'a confession'
          : row.mitigationState === null
            ? 'points nowhere real'
            : ASSURANCE[row.mitigationState] ?? row.mitigationState;
      lines.push(`| \`${row.record}\` | ${row.exposure} | ${target} | ${assurance} |`);
    }
    lines.push('');
  }

  const problems: string[] = [];
  for (const entry of initiatives) {
    for (const problem of checkInitiativeState(entry, gitStates.get(entry.id))) {
      problems.push(`- \`${problem.kind}\` **${problem.initiative}** — ${problem.detail}`);
    }
    for (const orphan of entry.orphanedMilestones) {
      problems.push(
        `- \`milestone-outside-section\` **${entry.id}** — \`${orphan.name || orphan.description.slice(0, 30)}\` ` +
          `lives under "${orphan.section}", so it is not counted in this initiative's progress.`
      );
    }
  }

  lines.push('## Problems', '', 'Ways this board would otherwise be quietly wrong.', '');
  if (problems.length === 0) {
    lines.push('_None._', '');
  } else {
    lines.push(...problems, '');
  }

  return lines.join('\n');
}

/** Regenerates `BOARD.md`, mirroring `regenerateDecisionMap`. */
export function regenerateBoard(opensprintDir: string): void {
  const initiatives = readInitiatives(opensprintDir);
  // The project root is the parent of opensprint/. Git may know nothing —
  // no repository, no trunk — and the check then reports exactly what it
  // reported before.
  const projectRoot = path.dirname(opensprintDir);
  const gitStates = new Map<string, import('./initiatives.js').InitiativeGitState>();
  for (const initiative of initiatives) {
    const state = readInitiativeGitState(projectRoot, initiative.id);
    if (state !== undefined) gitStates.set(initiative.id, state);
  }
  const board = renderBoard(initiatives, roadmapRows(opensprintDir, initiatives), gitStates);
  fs.writeFileSync(path.join(opensprintDir, BOARD_FILENAME), board, 'utf-8');
}
